from threading import Thread

def fast_sum(numbers):
    def local_sum(data, index, shared_list):
        total = 0
        for i in range(index, len(data)):
            total += data[i]
        shared_list[index] = total

    threads = []
    shared_list = [0] * 20

    for i in range(20):
        thread = Thread(target=local_sum, args=(numbers, i, shared_list))
        threads.append(thread)

    for thread in threads:
        thread.start()

    for thread in threads:
        thread.join()

    return sum(shared_list)

